-- Fix businesses that have wrong business types
-- First check vacation provider type ID
SELECT id, name, slug FROM businessTypes WHERE slug = 'vacation-provider';

-- Fix Chamonix Endurance - should be Coach (1), not Ski Shop (11)
UPDATE businesses SET businessTypeId = 1 WHERE slug = 'chamonix-endurance';

-- Fix Zermatt Ski Academy - should be Ski School (12), not Coach (1)
UPDATE businesses SET businessTypeId = 12 WHERE slug = 'zermatt-ski-academy';

-- Fix Nice Côte d'Azur Cycling - should be Cycling Studio (4) or Coach (1), not Ski Shop (11)
UPDATE businesses SET businessTypeId = 1 WHERE slug = 'nice-cote-dazur-cycling';

-- Fix Nordic Ski Norway - should be Ski School (12), not Coach (1)
UPDATE businesses SET businessTypeId = 12 WHERE slug = 'nordic-ski-norway';

-- Fix Whistler Endurance Sports - should be Vacation Provider (15), not Ski Shop (11)
UPDATE businesses SET businessTypeId = 15 WHERE slug = 'whistler-endurance-sports';

-- Fix Lake Louise Ski School - should be Ski School (12), not Coach (1)
UPDATE businesses SET businessTypeId = 12 WHERE slug = 'lake-louise-ski-school';

-- Fix Banff Sport Massage - should be Sports Massage (8), not Personal Trainer (10) 
UPDATE businesses SET businessTypeId = 8 WHERE slug = 'banff-sport-massage';

